import { useOptimistic, useRef, useState } from 'react';
import { wait } from './fakeApi';

export function OptimisticLike() {
  const [state, setState] = useState({ liked: false, count: 41 });
  const [optimistic, addOptimistic] = useOptimistic(state, (current, liked) => ({
    liked,
    count: current.count + (liked ? 1 : -1),
  }));
  const clicks = useRef(0);

  async function toggleAction() {
    const next = !state.liked;
    addOptimistic(next);
    await wait(800);
    clicks.current += 1;
    if (clicks.current % 3 === 0) return; // symulowany błąd: prawdziwy stan bez zmian
    setState((s) => ({ liked: next, count: s.count + (next ? 1 : -1) }));
  }

  return (
    <form action={toggleAction}>
      <button type="submit" aria-pressed={optimistic.liked} className={optimistic !== state ? 'pending' : undefined}>
        {optimistic.liked ? '♥' : '♡'} {optimistic.count}
      </button>
    </form>
  );
}

