import { useActionState, useOptimistic, useState } from 'react';
import { SubmitButton } from './SubmitButton';
import { wait } from './fakeApi';

export function TicketComments() {
  const [comments, setComments] = useState([{ id: 1, text: 'Sprawdzam logi serwera.' }]);
  const [optimisticComments, addOptimistic] = useOptimistic(comments, (current, text) => [
    ...current,
    { id: `temp-${current.length}`, text, sending: true },
  ]);

  async function addCommentAction(prevState, formData) {
    const text = String(formData.get('text') ?? '').trim();
    if (text.length < 3) return { error: 'Komentarz musi mieć co najmniej 3 znaki' };

    addOptimistic(text);
    await wait(800);
    if (text.includes('spam')) return { error: 'Serwer odrzucił komentarz' };

    setComments((list) => [...list, { id: Date.now(), text }]);
    return { error: null };
  }

  const [state, formAction] = useActionState(addCommentAction, { error: null });

  return (
    <section>
      <ul>
        {optimisticComments.map((c) => (
          <li key={c.id} className={c.sending ? 'comment--sending' : undefined}>
            {c.text} {c.sending && <small>wysyłanie…</small>}
          </li>
        ))}
      </ul>
      <form action={formAction}>
        <textarea name="text" aria-label="Nowy komentarz" />
        <SubmitButton pendingText="Wysyłanie">Dodaj komentarz</SubmitButton>
        {state.error && <p role="alert">{state.error}</p>}
      </form>
